import re

TITLE = re.compile(r"^[A-Z][A-Za-z ,]*$")
PAIR = re.compile(r"^(?P<key>[^:]+?):\s*(?P<value>.*?)\s*$")
COUNTERS = re.compile(r"^(?P<scope>\S.*?)\s+\((?P<cols>\w+(?:\s+\w+)+)\):\s*(?P<vals>[-\d.]+(?:\s+[-\d.]+)*)\s*$")


def parse(lines):
    rows, used, skip = [], [], []
    section = ""
    for j, ln in enumerate(lines):
        if not ln.strip():
            continue
        if not ln[0].isspace() and ":" not in ln and TITLE.match(ln.strip()):
            section = ln.strip()
            skip.append(j)
            continue
        hit = False
        for chunk in ln.split("\t"):
            chunk = chunk.strip()
            m = COUNTERS.match(chunk)
            if m:
                for col, val in zip(m.group("cols").split(), m.group("vals").split()):
                    rows.append({"section": section, "key": m.group("scope") + " " + col, "value": val})
                hit = True
                continue
            m = PAIR.match(chunk)
            if m:
                rows.append({"section": section, "key": m.group("key"), "value": m.group("value")})
                hit = True
        if hit:
            used.append(j)
    return {"blocks": [{"name": "fields", "kind": "table", "lines": used, "records": rows}],
            "skip": skip}
